<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';
use App\Services\RectificationService;use App\Support\Database;
$db=Database::connection();$match=(int)$db->query('SELECT id FROM matches WHERE status="homologated" AND deleted_at IS NULL ORDER BY id DESC LIMIT 1')->fetchColumn();if(!$match){fwrite(STDERR,"No homologated match fixture.\n");exit(1);}$db->beginTransaction();try{$service=new RectificationService($db);$old=$service->snapshot($match,null,'homologated');$request=$service->request($match,'E2E correction',null,['events']);$impact=$service->approve($request,null);$service->apply($request,null,$impact['requires_administrative_decision']?'keep bracket by decision':'');$s=$db->prepare('SELECT status FROM rectification_requests WHERE id=?');$s->execute([$request]);if($s->fetchColumn()!=='applied')throw new RuntimeException('Request not applied.');$s=$db->prepare('SELECT COUNT(*) FROM match_homologation_versions WHERE match_id=?');$s->execute([$match]);if((int)$s->fetchColumn()<2)throw new RuntimeException('Immutable versions missing.');$db->rollBack();echo "RECTIFICATION_E2E_OK\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
